            String k = String.join("", b);
            keys.add(k); byKey.put(k, b);
        }
        Collections.sort(keys);
        StringBuilder sb = new StringBuilder();
        sb.append(keys.size()).append('\n');
        for (String k : keys) for (String row : byKey.get(k)) sb.append(row).append('\n');
        System.out.print(sb);
    }
}

