import sys
n = int(sys.stdin.read().split()[0])
sols, cur = [], []
cols, d1, d2 = set(), set(), set()
def bt(r):
    if r == n:
        sols.append(['.' * c + 'Q' + '.' * (n - c - 1) for c in cur]); return
    for c in range(n):
        if c in cols or r - c in d1 or r + c in d2:
            continue
        cols.add(c); d1.add(r - c); d2.add(r + c); cur.append(c)
        bt(r + 1)
        cols.discard(c); d1.discard(r - c); d2.discard(r + c); cur.pop()
bt(0)
sols.sort()
print(len(sols))
for b in sols:
    for row in b:
        print(row)
